Adjustment Methods


Show code
reset_1 &lt;- function(x, v = 0.99999){
  pmin(x, v)
}

squash &lt;- function(x, eps = 1e-2) {
  x[x &gt; 0] &lt;- x[x &gt; 0] * (1 - 2 * eps) + eps
  x
}

offset &lt;- function(x, eps = 1e-2){
  x[x &gt; 0] &lt;- x[x &gt; 0] - eps
  x
}

rescale_p01p99 &lt;- function(x) {
  out &lt;- x
  is_nonzero &lt;- x != 0
  x_nz &lt;- x[is_nonzero]
  rng &lt;- range(x_nz, na.rm = TRUE)
  rescaled &lt;- (x_nz - rng[1]) / (rng[2] - rng[1])
  out[is_nonzero] &lt;- rescaled * 0.98 + 0.01
  out
}

map_range &lt;- function(x, min_val = 0.9) {
  out &lt;- x
  is_nonzero &lt;- x &gt; 0
  out[is_nonzero] &lt;- (x[is_nonzero] - min_val) / (1 - min_val) * 0.98 + 0.01
  out
}

Model Fitting Functions


Show code
fit_and_summary_zib &lt;- function(df, combined_formula = value ~ spiked, design = ~spiked){
  x &lt;- summary(glmmTMB(formula = combined_formula, ziformula = design, data = df, family = beta_family(link = "logit")))
  tmp &lt;- c(x$coefficients$cond[2, c(1,4)], x$coefficients$zi[2, c(1,4)])
  names(tmp) &lt;- c("beta", "p_beta", "z_beta", "z_p_beta")
  tmp
}

fit_and_summary_ob &lt;- function(df, combined_formula = value ~ spiked){
  x &lt;- summary(glmmTMB(formula = combined_formula, data = df, family = ordbeta()))
  tmp &lt;- x$coefficients$cond[2, c(1,4)]
  names(tmp) &lt;- c("beta", "p_beta")
  tmp
}

fit_and_summary_qb &lt;- function(df, combined_formula = value ~ spiked){
  x &lt;- summary(glm(formula = combined_formula, data = df, family = 'quasibinomial'))
  tmp &lt;- x$coefficients[2, c(1,4)]
  names(tmp) &lt;- c("beta", "p_beta")
  tmp
}
